export const commandGroups: CommandGroup[] = baseCommandGroups.map((group) => ({
  ...group,
  labelEn: commandGroupTranslations[group.id]?.label,
  descriptionEn: commandGroupTranslations[group.id]?.description,
  commands: group.commands.map((command) => ({ ...command, summaryEn: commandSummaryTranslations[command.name] })),
}));

export function localizedText(zh: string, en: string | undefined, language: string) {
  return language.startsWith("en") && en ? en : zh;
}

export const totalCommands = commandGroups.reduce((total, group) => total + group.commands.length, 0);

